30.4 Parte C · Estilo SLD con la paleta GeoIA
&lt;?xml version="1.0" encoding="UTF-8"?&gt;
&lt;StyledLayerDescriptor version="1.0.0" xmlns="http://www.opengis.net/sld"
  xmlns:ogc="http://www.opengis.net/ogc"&gt;
  &lt;NamedLayer&gt;&lt;Name&gt;senaletica&lt;/Name&gt;
    &lt;UserStyle&gt;&lt;FeatureTypeStyle&gt;&lt;Rule&gt;
      &lt;PointSymbolizer&gt;&lt;Graphic&gt;
        &lt;Mark&gt;&lt;WellKnownName&gt;circle&lt;/WellKnownName&gt;
          &lt;Fill&gt;&lt;CssParameter name="fill"&gt;#E8772A&lt;/CssParameter&gt;&lt;/Fill&gt;
          &lt;Stroke&gt;&lt;CssParameter name="stroke"&gt;#1B2A4A&lt;/CssParameter&gt;
                  &lt;CssParameter name="stroke-width"&gt;1.5&lt;/CssParameter&gt;&lt;/Stroke&gt;
        &lt;/Mark&gt;&lt;Size&gt;10&lt;/Size&gt;
      &lt;/Graphic&gt;&lt;/PointSymbolizer&gt;
    &lt;/Rule&gt;&lt;/FeatureTypeStyle&gt;&lt;/UserStyle&gt;
  &lt;/NamedLayer&gt;
&lt;/StyledLayerDescriptor&gt;
